/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('Task.v'); s=p.read_text().replace('''  destruct c, d; simpl; try discriminate;
    intros H E; try (injection E as E; subst); cbn in H;
    try match goal with |- _ => inversion H end.''','''  destruct c, d; simpl; try discriminate;
    intros H E; try (injection E as E; subst); cbn [cdiscrK] in H;
    match type of H with
    | context [kindEqDec.eq_dec ?k ?k] =>
        destruct (kindEqDec.eq_dec k k) as [F|F]; [|contradiction];
        replace F with (@eq_refl kind k) in H by apply UIP;
        simpl in H; inversion H
    end.''')
p.write_text(s)
PY
rocq compile -q -time -w -deprecated-missing-stdlib,-deprecated-from-Coq -R . Top Task.v >/tmp/time174.log 2>&1; tail -28 /tmp/time174.log"

